  worktreeDir: string,
  remoteName = "origin",
  options?: ShadowOptions,
): Promise<boolean> {
  const branchName = getBranchName(options);
  try {
    await runGitAsync(worktreeDir, ["push", "-u", remoteName, branchName]);
    return true;
  } catch {
