  execSync('git add README.md && git commit -m "initial"', {
    cwd: tempDir,
    stdio: 'pipe',
  });

  // kspec init --setup creates shadow branch + installs core skills
  const result = kspec('init --no-prompt --setup', tempDir, {
    env: { CLAUDECODE: '1', KSPEC_AUTHOR: '@test' },
